import { IReelEffects, IReelEvents, IServiceEvents, ISymbolData, ISymbolEvents } from '../../../types';

export interface ICascadeBounceSettings {
    duration: number;
    offset: number;
}

export interface ICascadeFallSettings {
    fallOffset: number | number[];
    fallTime: number | number[];
}

export interface ICascadeTeaseSettings {
    /** Delay (seconds) after existing on-screen symbols land before new symbols start dropping in */
    newSymbolsDelay: number;
    /** Extra delay (seconds) per reel index, so reels drop one after the other */
    reelStaggerDelay: number;
}

export interface ICascadeSettings {
    cascadeFallSettings: ICascadeFallSettings;
    cascadeBounceSettings: ICascadeBounceSettings;
    cascadeRemoveDelay: number;
    cascadeBlockFallDelay: number;
    cascadeTease: ICascadeTeaseSettings;
}

export enum CascadeState {
    FALLING = 3,
    REMOVAL = 2,
    PRE_CASCADING = 1,
    NOT_CASCADING = 0,
}

export interface ICascadeServiceEvents extends IServiceEvents {
    ON_CASCADE_COMPLETE: () => void,
    ON_CASCADE_STATE_CHANGED: () => void
}
export type GCServiceEvent = {
    serviceEvent: ICascadeServiceEvents
}
export interface ICascadeReelEffects extends IReelEffects {
    CASCADE_EFFECT: () => void,
}

export type GCReelEvent = {
    reelEvent: IReelEvents;
    reelEffect: ICascadeReelEffects;
}
export interface ICascadeSymbolEvent extends ISymbolEvents {
    REMOVE_FROM_CASCADE: () => void
}

export type GCSymbolEvent = {
    symbolEvent: ICascadeSymbolEvent;
}

export interface ICascadeSymbolData extends ISymbolData {
    removedFromCascade: boolean;
}

export interface IGCRSettings {
    fallTime: () => number;
    fallOffset: () => number;
}